            "usage": {
              "description": "Calendar lets the user pick a date or date range from a month grid. Use it in booking flows, scheduling UIs, date filters, or anywhere the user needs to see surrounding dates for context.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Set min and max dates to limit selection to a valid window, like only future dates for a booking or the current quarter for a report."
                },
                {
                  "guidance": true,
                  "description": "Use range mode when the user needs to pick a start and end date, like a trip or a time-off request."
                },
                {
                  "guidance": true,
                  "description": "Use dateConstraints to disable specific dates like weekends or holidays, and explain why they are unavailable."
                },
                {
                  "guidance": true,
                  "description": "Show two months side by side when the user frequently selects dates that span a month boundary."
                },
                {
                  "guidance": true,
                  "description": "For a custom month view, use useCalendarNavigation and useCalendarDays from @astryxdesign/core/Calendar. To show another calendar system, pass the same calendar to both and feed visibleCalendarMonths into useCalendarDays. The hooks default to gregory and never read the InternationalizationProvider calendar."
